  ["_CeladonMart3FSNESText"] = "¡Es una SUPER\nNINTENDO!",
  ["_CeladonMart3FSportsGameText"] = "¡Un juego de\ndeportes! ¡A mi\fpadre le gustan!",
  ["_CeladonMart4FCurrentFloorSignText"] = "¡Dilo con un\nregalo!\fP3: REGALOS\f¡Evolución\nEspecial!\f¡Diversas PIEDRAS\nElementales en\fventa!",
  ["_CeladonMart4FSuperNerdText"] = "¡Compraré una\nPOKé MUÑECA\fpara mi novia!",
  ["_CeladonMart4FYoungsterText"] = "¡Me dijeron una\ncosa!\f¡Puedes huir de\nun POKéMON\fsalvaje si le\ndistraes con una\fPOKé MUÑECA!",
  ["_CeladonMart5FCurrentFloorSignText"] = "P4: FARMACIA",
  ["_CeladonMart5FGentlemanText"] = "¡Los dispositivos\nde mejora de los\fPOKéMON sólo\nse venden aquí!\fUsa CALCIO para\naumentar las\fhabilidades\nESPECIALES.\fUsa CARBURANTE\npara aumentar la\fVELOCIDAD.",
  ["_CeladonMart5FSailorText"] = "¡He venido a por\ndispositivos de\fmejora de los\nPOKéMON!\fLas PROTEÍNAS\naumentan la\fpotencia del\nATAQUE.\fEl HIERRO aumenta\nla DEFENSA.",
  ["_CeladonMartRoofCurrentFloorSignText"] = "ÚLTIMO PISO:\nDISTRIBUIDORES",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "¡Tengo sed!\n¡Me gustaría\fbeber algo!\f¿Le das algo\nde beber?",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "¿Qué bebida\nquieres darle?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "¡No, gracias!\n¡No estoy tan\fsedienta!",
