  ["_OKExclamationText"] = "¡VALE!",
  ["_OakLabEmailText"] = "¡Aquí hay un\nmensaje e-mail!\f...\f¡Aviso a todos\nlos entrenadores\fde POKéMON!\f¡Los entrenadores\nde élite de la\fLIGA POKéMON\nestán listos\fpara desafiaros\na todos!\f¡Traed a vuestros\nmejores POKéMON\fy descubrid\nvuestra \fpuntuación como\nentrenadores!\fCG de la LIGA\nPOKéMON\fMESETA AÑIL\fPD: ¡PROF. OAK,\nvisítenos por\ffavor!...",
  ["_OakSpeechText1"] = "¡Hola a todos!\n¡Bienvenidos al\fmundo de POKéMON!\f¡Me llamo OAK!\n¡Pero la gente me\fllama el PROFESOR\nPOKéMON!",
  ["_OakSpeechText2A"] = "¡Este mundo está\nhabitado por unas\fcriaturas\nllamadas POKéMON!",
  ["_OakSpeechText2B"] = "Para algunos, los\nPOKéMON son\fmascotas. Pero\notros los usan\fpara pelear.\fEn cuanto a mí...\fEstudio a los\nPOKéMON como\fprofesión.",
  ["_OakSpeechText3"] = "¡{PLAYER}!\f¡Tu propia\nleyenda POKéMON\festá a punto de\ncomenzar!\f¡Te espera un\nmundo de sueños\fy aventuras con\nlos POKéMON!\f¡Adelante!",
  ["_OaksAideComeBackText"] = "¡Ah! Ya veo.\fCuando tengas {NUM:hOaksAideRequirement, 1, 3}\ntipos, vuelve a\fpor {RAM:wOaksAideRewardItemName}.",
  ["_OaksAideGotItemText"] = "¡{PLAYER} obtuvo\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "¡Bien! ¡Has\nlogrado {NUM:hOaksAideNumMonsOwned, 1, 3} tipos \fde POKéMON!\n¡Enhorabuena!\f¡Aquí tienes!",
  ["_OaksAideHiText"] = "¡Hola! ¿Te\nacuerdas de mí?\f¡Soy AYUDANTE\ndel PROF. OAK!\f¡Si atrapaste {NUM:hOaksAideRequirement, 1, 3}\ntipos de POKéMON,\fse supone que\ndebería darte\f{RAM:wOaksAideRewardItemName}!\f¡Bien {PLAYER}!\n¿Atrapaste por lo\fmenos {NUM:hOaksAideRequirement, 1, 3} tipos\nde POKéMON?",
  ["_OaksAideNoRoomText"] = "¡Oh! Ya veo que\nno tienes\fsitio para\n{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Veamos...\n¡Oh! ¡Atrapaste\fsolamente {NUM:hOaksAideNumMonsOwned, 1, 3}\ntipos de POKéMON!\fNecesitas {NUM:hOaksAideRequirement, 1, 3}\ntipos si quieres\f{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "¡El PROF. OAK es\nun experto en\fPOKéMON!\f¡Es admirado por\nmuchos de los\fentrenadores de\nPOKéMON!",
  ["_OaksLabGivePokeballsExplanationText"] = "Cuando aparezca\nun POKéMON\fsalvaje, lucha\ncontra él.\f¡Lánzale una\nPOKé BALL para\fcapturarlo!\f¡Pero esto no\nsiempre funciona!\f¡Un POKéMON\nsano podría huir!\f¡También cuenta\nla suerte!",
  ["_OaksLabLastMonText"] = "¡Ése es el último\nPOKéMON del\fPROF. OAK!",
  ["_OaksLabMonEnergeticText"] = "¡Este POKéMON es\nmuy energético!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "OAK: Ven a verme\nde vez en cuando.\f¡Tenme informado\nsobre cómo te va\fcon tu POKéDEX!",
  ["_OaksLabOak1DeliverParcelText"] = "OAK: ¡{PLAYER}!\f¿Cómo va tu\nPOKéMON?\f¡Creo que te\nquiere mucho!\f¡Pareces ser\nmuy hábil como\fentrenador de\nPOKéMON!\f¿Qué? ¿Tienes\nalgo para mí?\f{PLAYER} entregó\nel CORREO de OAK.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "OAK : ¡Encantado\nde verte! ¿Cómo\fva tu POKéDEX?\n¡Déjame que le\feche un vistazo!",
  ["_OaksLabOak1ParcelThanksText"] = "¡Ah, sí! ¡Es la\nPOKé BALL que\fhabía encargado!\n¡Gracias!",
