  ["_PersianDexEntry"] = "Aunque es muy\nadmirado por su\fpelo, es difícil\fde entrenar como\nmascota por su\fvoluble maldad",
  ["_PewterCityCooltrainerFText"] = "¡Dicen que los\nCLEFAIRY vinieron\fde la luna!\f¡Aparecieron tras\nla caída de la\fPIEDRA LUNAR en\nel MT. MOON!",
  ["_PewterCityCooltrainerMText"] = "¡No hay muchos\nentrenadores\fde POKéMON\npor aquí!\f¡Todos parecen\nCAMPISTAS, salvo\fBROCK, del\nGIMNASIO de la\fCIUDAD PLATEADA!",
  ["_PewterCityGymSignText"] = "LÍDER del GIMNASIO\nPOKéMON de la\fCIUDAD PLATEADA:\nBROCK\f¡El entrenador\nPOKéMON\fmás fuerte que\nuna roca!",
  ["_PewterCityMuseumSignText"] = "MUSEO DE LA\nCIENCIA DE LA\fCIUDAD PLATEADA",
  ["_PewterCityPokecenterGuyText"] = "(Bostezo)...\fCuando JIGGLYPUFF\ncanta, los\fPOKéMON se\nduermen...\f...Yo también...\n(Ronquido)...",
  ["_PewterCityPoliceNoticeSignText"] = "¡AVISO!\f¡Unos ladrones\nrobaron fósiles\fde POKéMON del\nMT. MOON!\f¡Avisad a la\nPOLICÍA de CIUDAD\fPLATEADA si\nsabéis algo!",
  ["_PewterCitySignText"] = "CIUDAD PLATEADA\nUna ciudad de\froca grisácea.",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "¿Has estado en\nel MUSEO?",
