  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "¡Pssss!\n¿Sabes lo que\festoy haciendo?",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "¡Utilizo el\nREPELENTE para\fechar de mi\njardín a los\fPOKéMON!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "¡Eso es! ¡Es un\nduro trabajo!",
  ["_PewterCityTrainerTipsText"] = "PISTAS ENTRENADOR\f¡Todo POKéMON\nque luche en una\fbatalla ganará\nEXPERIENCIA!",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "¡Si eres valiente\npelearás contra\fBROCK!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "¿Eres entrenador?\n¡BROCK está\fbuscando a nuevos\nadversarios!\f¡Sígueme!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "¡Es una MEDALLA\noficial de la\fLIGA POKéMON!\f¡El POKéMON\nque la tenga será\fmucho más fuerte!\f¡Y la técnica del\nDESTELLO podrá\fser utilizada\nen todo momento!",
  ["_PewterGymBrockPostBattleAdviceText"] = "¡En el mundo hay\ntodo tipo de\fentrenadores!\f¡Pareces ser\nmuy hábil como\fentrenador!\f¡Vete al GIMNASIO\nde CELESTE y pon\fa prueba tus\nhabilidades!",
  ["_PewterGymBrockPreBattleText"] = "¡Soy BROCK!\n¡GIM. LÍDER de la\fCIUDAD PLATEADA!\f¡Creo en la gran\nresistencia de\fla roca y en la\ndeterminación!\f¡Por eso todos\nmis POKéMON son\fdel tipo-roca!\f¿Todavía quieres\ndesafiarme? ¡Muy\fbien! ¡Enséñame\nlo que vales!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "No supe\napreciar lo que\fvales.\f¡Como prueba\nde tu victoria,\faquí tienes la\nMEDALLA-ROCA!\f¡{PLAYER} obtiene\nla MEDALLA-ROCA!",
  ["_PewterGymBrockWaitTakeThisText"] = "¡Espera! ¡Lleva\nesto contigo!",
