  ["_PewterGymCooltrainerMBattleText"] = "¡Alto ahí, niño!\f¡Todavía estás a\naños luz de retar\fa BROCK!",
  ["_PewterGymCooltrainerMEndBattleText"] = "¡Mm!\f¡Años luz no son\ntiempo! ¡Miden\fdistancia!",
  ["_PewterGymGuideAdviceText"] = "¡El 1er POKéMON\nque sale a luchar\fes el primero de\nla LISTA de\fPOKéMON!\f¡Cambiar el orden\nde los POKéMON\fpodría facilitar\nlos combates!",
