  ["_RockTunnelB1FHiker3EndBattleText"] = "\n¡Vamos, adelante!",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Cuando termines\ncon tu POKéDEX\f¿me la dejarás?",
