  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "\n¡Brgg! ¡Me das\ftanta envidia!",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Los jugadores\ndisfrazados\fvisten como los\nPOKéMON para\fdivertirse.",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "¿Qué sabes de\nesos jugadores\fdisfrazados?",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "Pues\neso es todo.",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Soy un artista,\nno un guerrero.",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Cuando estoy en\ncasa, dibujo a\flos POKéMON.",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "¡Uf!\n¡Estoy agotado!",
  ["_RockTunnelPokecenterFisherText"] = "¡Vendí una inútil\nPEPITA por 5000$!",
  ["_RockTunnelPokecenterGentlemanText"] = "¡Los POKéMON\nde ciertos\felementos son más\no menos fuertes\fque otros!",
  ["_RockTunnelPokecenterGuyText"] = "¡Dicen que hay\nGHOST en el\fPUEBLO LAVANDA!",
  ["_RocketHide3AfterBattleText3"] = "¡Venga, adelante!\n¡Pero necesitarás\fla LLAVE DEL\nASCENSOR!",
  ["_RocketHideout3BattleText"] = "¡Nos dijeron\ndesde arriba\fque venías!",
  ["_RocketHideout3EndBattleText3"] = "¿Qué?\n¿He perdido? ¡NO!",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "¿Vas a luchar\ncontra el\fTEAM ROCKET?",
  ["_RocketHideoutB1FRocket1BattleText"] = "¿Quién eres tú?\n¿Y cómo has\fllegado aquí?",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "¡Auuu!\n¡He perdido!",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "¡No te vas a\nsalir con la\ftuya, mocoso!",
  ["_RocketHideoutB1FRocket2BattleText"] = "¡Has destrozado\nnuestros planes!",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "\n¡Chamuscado!",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "¿El SCOPE SILPH?\n¡No sé dónde\festá!",
  ["_RocketHideoutB1FRocket3BattleText"] = "¡Alerta!\n¡Hay un intruso!",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "¡¡¡No\npude hacerlo!!!",
