  ["_RocketHideoutB1FRocket4BattleText"] = "¿Por qué has\nvenido aquí?",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "¡Esto\nno funcionará!",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "¡Oh-oh, esa pelea\nabrió la puerta!",
  ["_RocketHideoutB1FRocket5BattleText"] = "¿Te has perdido,\npequeñajo?",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "\n¿Por qué...?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "El CG del TEAM\nROCKET tiene 4\fsótanos. ¿Podrás\nllegar al JEFE?",
  ["_RocketHideoutB2FRocketBattleText"] = "¡El JEFE dijo que\nse pueden ver\ffantasmas con\nel SCOPE SILPH!",
  ["_RocketHideoutB2FRocketEndBattleText"] = "\n¡Me rindo!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "¿El SCOPE SILPH?\nLa máquina que\frobó el JEFE.\nDebe de estar\fpor aquí.",
  ["_RocketHideoutB3FRocket1BattleText"] = "¡Deja de meterte\nen los asuntos\fdel TEAM ROCKET!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "¡Uff!\n¡Me tumbaron!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Ya veo que has\nentrenado a tus\fPOKéMON con\nmucho cuidado.\f¡Un niño como tú\njamás entendería\fcuáles son mis\nplanes!\f¡En esta ocasión\nte dejaré pasar!\fEspero que nos\nvolvamos a ver.",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "¡Mmm! ¡Estoy muy\nimpresionado de\fque hayas llegado\nhasta aquí!",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "¿QUÉ?\n¡Esto es\fimposible!",
  ["_RocketHideoutB4FRocket1AfterBattleText"] = "¿Tienes algo\nen contra del\fTEAM ROCKET?",
  ["_RocketHideoutB4FRocket1BattleText"] = "¡Te conozco! ¡Tú\narruinaste\fnuestros planes\nen MT. MOON!",
  ["_RocketHideoutB4FRocket1EndBattleText"] = "\n¡Chamuscado\fotra vez!",
