  ["_RocketHideoutB4FRocket2BattleText"] = "¿Acaso no ves\nla belleza de\fnuestros actos\nmalvados?",
  ["_RocketHideoutB4FRocket2EndBattleText"] = "¡Ayayay!",
  ["_RocketHideoutB4FRocket3AfterBattleText"] = "¡Oh no! ¡He\nperdido la LLAVE\fdel ASCENSOR!",
  ["_RocketHideoutB4FRocket3BattleText"] = "¿No funciona el\nascensor? ¿Quién\ftiene la LLAVE\ndel ASCENSOR?",
  ["_RocketHideoutB4FRocket3EndBattleText"] = "¡No!",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "¡Parece necesitar\nuna llave!",
  ["_RoseText"] = "creció!",
  ["_Route10CooltrainerF1AfterBattleText"] = "Vi a algunos\nPOKéMANÍACOS\fpor ahí.",
