  ["_Route10CooltrainerF1EndBattleText"] = "\n¡Volví a perder!",
  ["_Route10CooltrainerF2AfterBattleText"] = "¡Estos POKéMON\nson tan robustos!\f¡Debería haber\nalguno rosa con\fbonitas flores!",
  ["_Route10CooltrainerF2BattleText"] = "¡Me siento débil\ntras la escalada!",
