  ["_Route11Youngster2BattleText"] = "¡Soy un nuevo\nentrenador! ¡Pero\fcreo que puedo\nganar!",
  ["_Route11Youngster2EndBattleText"] = "¡Mis\nPOKéMON\fperdieron!",
  ["_Route11Youngster3AfterBattleText"] = "Hay un gordo\nPOKéMON que\fbaja de las\nmontañas.\fEs muy fuerte,\npero primero hay\fque atraparlo.",
