  ["_Route12Fisher5EndBattleText"] = "\n¡He perdido!",
  ["_Route12Gate1FGuardText"] = "Hay una bonita\nvista arriba.",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "¡{PLAYER} obtuvo\nla MT39!",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "¡La MT39 es un\nataque que se\fllama RAPIDEZ!\fEs muy preciso.\nÚsalo en aquellas\fbatallas que no\npuedas permitirte\fperder.",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "¡No tienes sitio\npara esto!",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "Las cenizas de\nmis POKéMON están\fguardadas en la\nTORRE POKéMON.\fPuedes quedarte\ncon mi MT. Ya no\fla necesito...",
  ["_Route12Gate2FLeftBinocularsText"] = "Miraste por los\nprismáticos.\f¡Un hombre está\npescando!",
  ["_Route12Gate2FRightBinocularsText"] = "Miraste por los\nprismáticos.\f¡Es la TORRE\nPOKéMON!",
