  ["_Route12SnorlaxText"] = "¡Un POKéMON\ndormido bloquea\fel camino!",
  ["_Route12SnorlaxWokeUpText"] = "¡SNORLAX se\ndespertó!\f¡Se enfadó mucho\ny ataca furioso!",
  ["_Route12SportFishingSignText"] = "ZONA DE PESCA",
