  ["_Route13Beauty2BattleText"] = "¿Quieres jugar\nconmigo a los\fPOKéMON?",
  ["_Route13Beauty2EndBattleText"] = "\n¿Ya se ha\fterminado?",
  ["_Route13BikerAfterBattleText"] = "¡Olvídame!",
  ["_Route13BikerBattleText"] = "¿Y tú\nqué miras?",
  ["_Route13BikerEndBattleText"] = "¡Vaya!\n¡Derrapé!",
