  ["_Route13CooltrainerF2BattleText"] = "¡Qué chulas son\ntus MEDALLAS!",
  ["_Route13CooltrainerF2EndBattleText"] = "¡No\nfue suficiente!",
  ["_Route13CooltrainerF3AfterBattleText"] = "¡Tienes que hacer\nluchar a tus\fPOKéMON para\nfortalecerlos!",
  ["_Route13CooltrainerF3BattleText"] = "Mis simpáticos\nPOKéMON desean\fconocerte.",
