  ["_Route9Youngster2EndBattleText"] = "Mis\nbichos...",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "¡Dañaste a mis\npobres POKéMON!\f¡¡¡Y exijo que\nlos cures en\fun CENTRO\nPOKéMON!!!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "¡Recogí estos\nPOKéMON por\ftodo el mundo!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "¡Oh no!\n¡Viajé por todo\fel mundo\nsólo por ellos!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "¡Deberías\nportarte bien\fcon los amigos!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "¡Viajo solo!\f¡Mis POKéMON\nson mis únicos\famigos!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "¡Oh!\n¡Mis amigos!",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "¡Me gustaría que\nme dejaras solo!\f¡¡Fuera de aquí!!",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "¡Oye tú, mocoso!\n¿Cómo te atreves\fa entrar aquí?",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "¡Oye!\n¡¡Eres un\fniño muy malo!!",
  ["_SSAnne1FRoomsGentleman3Text"] = "¡Ssh! ¡Soy agente\nde POLICÍA!\f¡Estoy siguiendo\nla pista del\fTEAM ROCKET!",
  ["_SSAnne1FRoomsGirl1Text"] = "¡Camarero, me\ngustaría tomar\funa tarta de\ncerezas!",
  ["_SSAnne1FRoomsGirl2Text"] = "¡Viajamos en\ncrucero por\ftodo el mundo!",
  ["_SSAnne1FRoomsLittleGirlText"] = "¡Siempre viajo\ncon WIGGLYTUFF!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "¡Los cruceros son\ntan elegantes y\facogedores!",
  ["_SSAnne1FRoomsWigglytuffText"] = "WIGGLYTUFF: ¡Wig\nTuuuf, Tuuuf!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Seamos amigos,\n¿vale?\f¡Y así podremos\nintercambiar\fPOKéMON!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "¡Me gustan los\nPOKéMON!\f¿Y a ti?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "¡Guauu!\n¡Eres estupendo!",
  ["_SSAnne1FSailorText"] = "¡Los pasajeros\nse están\fimpacientando!\f¡Los que están\nmás aburridos\fpodrían retarte!",
  ["_SSAnne1FWaiterText"] = "¡Bonjour! ¡Soy\nel camarero de\feste barco!\f¡Encantado de\nservirte en todo\flo que quieras!\f¡Pareces del tipo\nfuerte y callado!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Decían\nque había un\fmaestro del CORTE\na bordo.\f¡Pero sólo era\nun viejo mareado!\f¡Sin embargo, la\ntécnica del CORTE\fes muy útil!\f¡Deberías ir\na verle!\f¡Hasta luego!",
  ["_SSAnne2FRivalDefeatedText"] = "¡Vaya!\f¡Parece que has\nentrenado bien\fa tus POKéMON!",
  ["_SSAnne2FRivalText"] = "{RIVAL}:\n¡Bonjour {PLAYER}!\f¡Ya sabía yo\nque te vería\fpor aquí!\f¿{PLAYER}, de\nverdad fuiste\finvitado?\f¿Y qué tal va\ntu POKéDEX?\f¡Ya tengo 40\nPOKéMON,\fchaval!\f¡Están por todas\npartes!\f¡Adéntrate en\nlas zonas de\fhierba alta!",
  ["_SSAnne2FRivalVictoryText"] = "¡{PLAYER}!\n¿Estás mareado?\f¡Pues deberías\nponerte en forma,\famigo!",
  ["_SSAnne2FRoomsBeautyText"] = "¡Dicen que hay\nmucha gente\fque se marea!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "¡El CAPITÁN\nparecía muy\fmareado y pálido!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "¡Oh! ¡Adoro a\ntus fuertes\fPOKéMON!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Nunca te había\nvisto en la\ffiesta.",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "¡Oye!\n¡¡¡No te pongas\fnervioso!!!",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "¿Una fiesta?\fLa fiesta del\ncrucero debe de\fhaber terminado.",
  ["_SSAnne2FRoomsFisherBattleText"] = "¡Mira lo que\nhe pescado!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "\n¡Estoy acabado!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "¡Hace 15 años, yo\nhabría ganado!",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "¡Competir contra\nlos jóvenes me\fmantiene joven!",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "¡Buena\npelea! ¡Vuelvo a\fsentirme joven!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "¡Prefiero a\nlos POKéMON\ffuertes y raros!",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "¿Qué prefieres,\nun POKéMON fuerte\fo uno raro?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "¡Debo\nfelicitarte!",
  ["_SSAnne2FRoomsGentleman3Text"] = "¡Durante todos\nmis viajes jamás\fhabía visto a un\nPOKéMON que\fdurmiera tanto!\f¡Era algo\nasí!...",
  ["_SSAnne2FRoomsGentleman4Text"] = "¡Ah sí! ¡Vi a\nunos POKéMON\ftransportando a\ngente por el\fagua!",
  ["_SSAnne2FRoomsGentleman5Text"] = "¿Has ido a la\nZONA DE SAFARI\fen la CIUDAD\nFUCSIA?\f¡Había muchos\ntipos raros de\fPOKéMON!",
  ["_SSAnne2FRoomsGrampsText"] = "Los POKéMON\npueden CORTAR\fpequeños\narbustos.",
  ["_SSAnne2FRoomsLittleBoyText"] = "¡Mi padre y yo\npensamos que la\fZONA DE SAFARI\nes genial!",
  ["_SSAnne2FWaiterText"] = "¡Este lujoso\nbarco es para\flos entrenadores!\f¡En cada puerto\ncelebramos una\ffiesta para los\nentrenadores!",
  ["_SSAnne3FSailorText"] = "¡Nuestro CAPITÁN\nes un maestro de\fla esgrima!\f¡Y hasta enseña\na los POKéMON\fla técnica del\nCORTE!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "¡Yo también te\niba a hacer mi\fayudante!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "¡Hola forastero!\n¡Para y hablemos!\f¡Todos mis\nPOKéMON vienen\fdel mar!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "\n¡Maldición!\f¡Dejé que se me\nescapara ése!",
  ["_SSAnneB1FRoomsMachokeText"] = "MACHOKE: ¡Cho!\n¡Choke Cho!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "¡Ajá! ¿Quieres\nser marinero?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "¡Ya sabes lo que\ndicen sobre los\fmarineros y\nlas peleas!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "\n¡Has peleado muy\fbien, compañero!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "¿Viste al GURÚ\nde los PESCADORES\fen CIUDAD CARMÍN?",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "¡Está en juego mi\nfama de marinero!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "\n¡Tu espíritu\fme hundió!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "¡Pescamos a\ntodos nuestros\fPOKéMON\nen alta mar!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "¡Los marineros\ntambién tenemos\fPOKéMON!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "¡Eres\nbastante bueno!",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "Los POKéMON del\nmar viven en las\fprofundidades.\n¡Necesitarás\funa CAÑA!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "¡Me gustan los\nniños activos\fcomo tú!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "¡Argh!\n¡He perdido!",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "A veces, algunas\nmedusas caen\fen el barco.",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "¡Como pierdas\ncaminarás por el\ftablón, amigo!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "¡Argh!\n¡Derrotado\fpor un niño!",
  ["_SSAnneB1FRoomsSuperNerdText"] = "¡Mi amigo,\nMACHOKE, es\fsúper fuerte!\f¡Tiene tanta\nFUERZA que puede\fmover hasta\ngrandes rocas!",
  ["_SSAnneBowCooltrainerMText"] = "¡Uff! Me siento\nfatal...\fHe salido a\ntomar el aire.",
  ["_SSAnneBowSailor1Text"] = "¡Limpiar las\ncubiertas es un\ftrabajo duro!",
  ["_SSAnneBowSailor2AfterBattleText"] = "¿Cuántos tipos\nde POKéMON\fcrees que hay?",
  ["_SSAnneBowSailor2BattleText"] = "¡Eh, amigo!\f¡Bailemos una\njota!",
  ["_SSAnneBowSailor2EndBattleText"] = "¡Eres\nimpresionante!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Mi papá decía\nque hay 100 tipos\fde POKéMON. Pero\nyo creo que\fhay más.",
  ["_SSAnneBowSailor3BattleText"] = "¡Ah del barco!\n¿Estás mareado?",
  ["_SSAnneBowSailor3EndBattleText"] = "¡No\ntuve cuidado!",
  ["_SSAnneBowSuperNerdText"] = "¡Se acabó la\nfiesta! ¡El barco\fzarpará pronto!",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "¡Oh no! ¡No\ntienes sitio\fpara esto!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "CAPITÁN: ¡Uff!\n¡Gracias! Ya me\fsiento mucho\nmejor...\f¿Quieres ver mi\ntécnica de\fCORTAR?\fTe la mostraría\nsi no estuviera\ftan mareado.\f¡Ya sé!\n¡Toma esto!\f¡Enséñasela a tu\nPOKéMON y en\fbreve estará\nCORTANDO!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "CAPITÁN: ¡Bien!\f¡Ahora que ya no\nestoy mareado,\fcreo que\ndeberíamos irnos!",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "¡{PLAYER} obtiene\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "CAPITÁN: ¡Puajj!\nMe siento fatal.\fMe he mareado...\f¡{PLAYER} le dio\nun masaje al\fCAPITÁN!\f(Scratch)...\n(Scratch)...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "Comó combatir el\nMareo...\f¡El CAPITÁN está\nleyendo esto!",
  ["_SSAnneCaptainsRoomTrashText"] = "¡Puaj! ¡No debería\nhaber mirado!",
  ["_SSAnneKitchenCook1Text"] = "¡Hola, pequeñajo!\n¡Ahora estamos\focupados!\n¡Fuera de aquí!",
  ["_SSAnneKitchenCook2Text"] = "Vi una bola muy\nrara en la\fbasura.",
  ["_SSAnneKitchenCook3Text"] = "¡Estoy tan\nocupado que me\festoy mareando!",
  ["_SSAnneKitchenCook4Text"] = "¿Por qué?\n¿Por qué yo?\f¡Me paso todo\nel día pelando\fpatatas!",
  ["_SSAnneKitchenCook5Text"] = "¿Has oído hablar\nde SNORLAX?\f¡Se pasa todo el\ndía comiendo y\fdurmiendo!",
  ["_SSAnneKitchenCook6Text"] = "Sniff...sniff...\fYo sólo pelo\ncebollas...\fSniff...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "¡Ejem! ¡Por algo\nsoy el CHEF!\fEl menú es:",
  ["_SSTicketNoRoomText"] = "Llevas demasiadas\ncosas, chico.",
  ["_SSTicketReceivedText"] = "¡{PLAYER} obtuvo\n{RAM:wStringBuffer}!",
  ["_SafariZoneAngryText"] = "¡El {RAM:wEnemyMonNick}\nsalvaje está\fenfadado!",
  ["_SafariZoneCenterRestHouseGirlText"] = "SARA: ¿Adónde\nfue mi amigo\fERIC?",
  ["_SafariZoneCenterRestHouseScientistText"] = "¡Estoy atrapando\nPOKéMON para\fllevarlos a casa\ncomo regalos!",
  ["_SafariZoneCenterRestHouseSignText"] = "CASA DE REPOSO",
  ["_SafariZoneCenterTrainerTipsSignText"] = "PISTAS ENTRENADOR\f¡Pulsa START para\nsaber cuánto\ftiempo te queda!",
  ["_SafariZoneEastRestHouseRockerText"] = "¡Capturé a un\nCHANSEY!\f¡Y por eso todos\nmis esfuerzos han\fmerecido la pena!",
  ["_SafariZoneEastRestHouseScientistText"] = "¿Cuántos has\ncapturado? ¡Yo\festoy agotado de\ntanto trabajar!",
  ["_SafariZoneEastRestHouseSignText"] = "CASA DE REPOSO",
  ["_SafariZoneEastRestHouseSilphWorkerMText"] = "¡Ufff! ¡Estoy\nagotado de tanta\fdiversión!",
  ["_SafariZoneEastSignText"] = "ZONA CENTRAL\nNORTE: ÁREA 2",
  ["_SafariZoneEastTrainerTipsText"] = "PISTAS ENTRENADOR\f¡El tiempo\nrestante sólo\fse verá reducido\ncuando camines!",
  ["_SafariZoneEatingText"] = "¡El {RAM:wEnemyMonNick}\nsalvaje está\fcomiendo!",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "¡Te avisaremos\ncuando se agoten\ftus SAFARI BALL\no tu tiempo!",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "¿Has tenido buena\ncaza? ¡Vuelve\fcuando quieras!",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "¡Buena suerte!",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "¿Ya te vas?",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "¡Uuups! ¡No hay\nbastante dinero!",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "¡Bien! ¡Vuelve\ncuando quieras!",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Devuelve las\nSAFARI BALL que\fte sobren.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "¡Bienvenido a la\nZONA del SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "¡Son 500$,\npor favor!\fAquí sólo usamos\ncierto tipo de\fPOKé BALL.\f¡{PLAYER} obtuvo\n30 SAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "¡Por sólo 500$,\npodrás atrapar a\ftodos los POKéMON\nque quieras en\fel parque!\f¿Te gustaría\nunirte a la caza?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "¡Hola! ¿Es tu\nprimera vez aquí?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "La ZONA-SAFARI\nincluye 4 áreas.\fCada zona tiene\ndiferentes tipos\fde POKéMON. ¡Usa\nlas SAFARI BALL\fpara atraparlos!\f¡Si agotas el\ntiempo o las\fSAFARI BALL, el\njuego se dará\fpor terminado!\f¡Antes de ir,\nabre una nueva\fCAJA POKéMON\ny tendrás más\fsitio para nuevos\nPOKéMON!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "¡Perdona, vienes\nmucho por aquí!",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "¡Mi EEVEE se\ntransformó en un\fFLAREON!\f¡Pero el EEVEE de\nun amigo se\ftransformó en\nun VAPOREON!\f¿Por qué?",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Dirígete al área\nmás profunda del\fSAFARI. ¡Ganarás\nun premio!",
  ["_SafariZoneNorthRestHouseScientistText"] = "Puedes quedarte\ncon cualquier\fobjeto encontrado\nen esta zona.\f¡Pero te quedarás\nsin tiempo si\fintentas coger\ntodos a la vez!",
  ["_SafariZoneNorthRestHouseSignText"] = "CASA DE REPOSO",
  ["_SafariZoneNorthSignText"] = "ÁREA 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "PISTAS ENTRENADOR\f¡La CASA SECRETA\nsigue estando\fjusto delante!",
  ["_SafariZoneNorthTrainerTips2Text"] = "PISTAS ENTRENADOR\f¡Los POKéMON\nse ocultan entre\fla alta hierba!\fZigzaguea por\nzonas de hierba\fpara que salgan.",
  ["_SafariZoneNorthTrainerTips3Text"] = "PISTAS ENTRENADOR\f¡Encuentra la\nCASA SECRETA y\fganarás una MO!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "¡La MO03 es SURF!\f¡Un POKéMON\npodrá llevarte\fpor el agua!\f¡Y esta MO puede\nser utilizada una\fy otra vez!\f¡Tienes muchísima\nsuerte! ¡Eres el\fganador de este\nfabuloso premio!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "¡No tienes sitio\npara este premio\ftan fabuloso!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "¡Ah! ¡Por fin!\f¡Eres el primero\nque llega a la\fCASA SECRETA!\fEstaba empezando\na preocuparme\fque nadie ganara\nnuestro premio.\f¡Enhorabuena!\n¡Eres el ganador!",
  ["_SafariZoneWestFindWardensTeethSignText"] = "AVISO\fEncuentra los\nDIENTES DE ORO\fperdidos del\nGUARDA del\fSAFARI. Están\npor aquí.\f¡Se ofrece\nrecompensa!\fContactar con\nel GUARDA.",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Utilizar CEBO te\npermitirá atrapar\fmás fácilmente a\nlos POKéMON.",
  ["_SafariZoneWestRestHouseScientistText"] = "Tirar PIEDRAS a\nlos POKéMON\fpodría hacerles\nhuir, pero\fserán más fáciles\nde atrapar.",
  ["_SafariZoneWestRestHouseSignText"] = "CASA DE REPOSO",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "Caminé mucho,\npero no he visto\fa los POKéMON\nque quería.",
  ["_SafariZoneWestSignText"] = "ZONA 3\nESTE: ÁREA\fCENTRAL",
  ["_SafariZoneWestTrainerTipsText"] = "PISTAS ENTRENADOR\f¡Operación\nExploración\fde la Zona!\f¡La búsqueda de\nla CASA SECRETA!",
  ["_SaffronCityFightingDojoSignText"] = "DOJO-KARATE",
  ["_SaffronCityGentlemanText"] = "Volé aquí en mi\nPIDGEOT cuando\fsupe de SILPH.\f¿Ya se acabó?\nMe perdí toda\fla acción.",
  ["_SaffronCityGymSignText"] = "LÍDER del GIMNASIO\nPOKéMON de la\fCIUDAD AZAFRÁN:\nSABRINA\f¡Maestra de los\nPOKéMON\fpsíquicos!",
  ["_SaffronCityMrPsychicsHouseSignText"] = "CASA DEL\nSR. PSÍQUICO",
  ["_SaffronCityPidgeotText"] = "PIDGEOT: ¡Pid pid!",
  ["_SaffronCityPokecenterGuyText1"] = "¡Sería estupendo\nque el ALTO MANDO\fviniera y\nmachacara al\fTEAM ROCKET!",
  ["_SaffronCityPokecenterGuyText2"] = "¡El TEAM ROCKET\nse ha ido! ¡Ahora\fpodemos salir sin\npeligro! ¡Bien!",
  ["_SaffronCityRockerText"] = "Vi al JEFE ROCKET\nescapando del\fedificio SILPH.",
  ["_SaffronCityRocket1Text"] = "¿Qué quieres?\n¡Lárgate!",
  ["_SaffronCityRocket2Text"] = "¡El JEFE dice que\ninvadirá esta\fciudad!",
  ["_SaffronCityRocket3Text"] = "¡Fuera del\ncamino!",
  ["_SaffronCityRocket4Text"] = "¡AZAFRÁN es del\nTEAM ROCKET!",
  ["_SaffronCityRocket5Text"] = "¡Ser malo me hace\nsentir tan vivo!",
  ["_SaffronCityRocket6Text"] = "¡Au! ¡Cuidado por\ndonde caminas!",
  ["_SaffronCityRocket7Text"] = "¡Con SILPH bajo\ncontrol, podemos\fexplotar a los\nPOKéMON de\ftodo el mundo!",
  ["_SaffronCityRocket8Text"] = "Soy el guarda de\nseguridad.\f¡No permito\nentrar a chicos\fsospechosos!",
  ["_SaffronCityRocket9Text"] = "...\n(Ronquido)...\f¡Ja! ¡Está\ndurmiendo la\fsiesta!",
  ["_SaffronCityScientistText"] = "¿Venciste tú solo\nal TEAM ROCKET?\f¡Qué increíble!",
  ["_SaffronCitySignText"] = "CIUDAD AZAFRÁN\nLa brillante y\fdorada tierra del\ncomercio.",
  ["_SaffronCitySilphCoLatestProductSignText"] = "¡Lo último de\nSILPH!\fLanzado para ser\ndecisivo...",
  ["_SaffronCitySilphCoSignText"] = "EDIFICIO-OFICINAS\nde SILPH S.A.",
  ["_SaffronCitySilphWorkerFText"] = "La gente puede\nregresar ahora a\fAZAFRÁN.",
  ["_SaffronCitySilphWorkerMText"] = "¡El TEAM ROCKET\nse ha marchado!\f¡Ahora podemos\nsalir otra vez!",
  ["_SaffronCityTrainerTips1Text"] = "PISTAS ENTRENADOR\fCURA TOTAL cura\ntodo malestar,\fcomo el sueño y\nlas quemaduras.\fCuesta un poco\nmás, pero merece\fla pena.",
  ["_SaffronCityTrainerTips2Text"] = "PISTAS ENTRENADOR\fLa nueva SÚPER\nBALL ofrece una\fmayor velocidad\nde captura.\fPruébala con\nesos POKéMON\ftan difíciles de\natrapar.",
  ["_SaffronGateGuardGeeImThirstyText"] = "Estoy de guardia.\n¡Uauu! ¡Qué sed\ftengo!\fEspera. La ruta\nestá cerrada.",
  ["_SaffronGateGuardImParchedText"] = "¡Uauu, chico!\n¡Estoy sediento!\f...\n¿Eh? ¿Me das\fesa bebida? \n¡Gracias chaval!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "¡Oye! ¡Gracias\npor las bebidas!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "...\nGlu glu...\f...\n(Trago)...\fSi quieres ir a\nCIUDAD AZAFRÁN...\f...\nPuedes pasar...\f¡Compartiré esto\ncon los otros\fguardias!",
  ["_SaffronGymChanneler1AfterBattleText"] = "¡En una pelea de\niguales, ganará\fquien tenga más\nvoluntad!\f¡Si quieres ganar\na SABRINA, piensa\fsólo en ganar!",
  ["_SaffronGymChanneler1BattleText"] = "¡SABRINA es más\njoven que yo,\fpero la respeto!",
  ["_SaffronGymChanneler1EndBattleText"] = "\n¡Vaya fallo!",
  ["_SaffronGymChanneler2AfterBattleText"] = "¡Debo enseñarles\nmejores técnicas\fa mis POKéMON!",
  ["_SaffronGymChanneler2BattleText"] = "Los POKéMON\nacaban teniendo\fel aspecto de sus\nentrenadores.\f¡Pues tus POKéMON\nparecen fuertes!",
  ["_SaffronGymChanneler2EndBattleText"] = "\n¡Lo sabía!",
  ["_SaffronGymChanneler3AfterBattleText"] = "Sabía que esto\niba a pasar.",
  ["_SaffronGymChanneler3BattleText"] = "¡Tú y yo!\nNuestros POKéMON\fdeben luchar.",
  ["_SaffronGymChanneler3EndBattleText"] = "\n¡Al final perdí!",
  ["_SaffronGymGuideBeatSabrinaText"] = "¿Poder mental?\f¡Si yo lo tuviera\nme haría rico en\flas tragaperras!",
  ["_SaffronGymGuideChampInMakingText"] = "¡Hola, posible\ncampeón!\f¡Los POKéMON\nde SABRINA usan\fel poder de la\nmente y no la\ffuerza!\f¡Los POKéMON\nguerreros son\fdébiles contra\nlos POKéMON\fpsíquicos!\f¡Se debilitan\nantes de poderse\fpreparar!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "¡Con la MEDALLA\nPANTANO, todo\fPOKéMON con\nnivel inferior a 70 te obedecerá!\f¡Los POKéMON más\nfuertes ignorarán\ftus órdenes en\nla batalla!\f¡No entrenes\ndemasiado a\ftus POKéMON!\f¡Espera, llévate\nesta MT!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "¡Todo el mundo\ntiene poderes\fmentales, pero la\ngente lo ignora!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "¡Estoy\nimpresionada!\fAcepto mi\nderrota.\f¡Admito que no\nfui lo bastante\ffuerte y perdí!\f¡Has ganado la\nMEDALLA del\fPANTANO!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "¡{PLAYER} obtiene\nla MT46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "¡Tu mochila está\nllena de otros\fobjetos!",
  ["_SaffronGymSabrinaText"] = "¡Tuve una visión\nde tu llegada!\f¡Tengo poderes\npsíquicos desde\fque era niña!\fPrimero aprendí\na doblar cucharas\fcon mi mente.\f¡Odio luchar, \npero si quieres\fpuedo enseñarte\nmis poderes!",
  ["_SaffronGymYoungster1AfterBattleText"] = "¡Los POKéMON\npsíquicos temen\fsólo a los bichos\ny fantasmas!",
  ["_SaffronGymYoungster1BattleText"] = "¿Nuestro oculto\npoder te asusta?",
  ["_SaffronGymYoungster1EndBattleText"] = "¡Jamás lo\nhubiera pensado!",
  ["_SaffronGymYoungster2AfterBattleText"] = "¡SABRINA ganó al\nMAESTRO de KARATE\fde la puerta de\nal lado!",
  ["_SaffronGymYoungster2BattleText"] = "¡Sabes que sólo\ntu poder no es\fsuficiente!",
  ["_SaffronGymYoungster2EndBattleText"] = "¡No me\nlo puedo creer!",
  ["_SaffronGymYoungster3AfterBattleText"] = "En la CIUDAD\nAZAFRÁN solía\fhaber 2 GIMNASIOS\nPOKéMON.\f¡El DOJO-KARATE\nde aquí al lado\fperdió su\ncondición de\fGIMNASIO cuando\nlos machacamos!",
  ["_SaffronGymYoungster3BattleText"] = "¡SABRINA es joven,\npero es nuestra\fLÍDER!\f¡No llegarás a\nella fácilmente!",
  ["_SaffronGymYoungster3EndBattleText"] = "¡No pude\nconcentrarme!",
  ["_SaffronGymYoungster4AfterBattleText"] = "¡Tienes razón!\n¡Usé la telepatía\fpara leer tu\nmente!",
  ["_SaffronGymYoungster4BattleText"] = "¡El GIMNASIO\nPOKéMON de\fAZAFRÁN es famoso\npor sus médiums!\f¡Quieres ver a\nSABRINA!\f¡Lo sé!",
  ["_SaffronGymYoungster4EndBattleText"] = "¡Arrrgg!",
  ["_SaffronMartCooltrainerFText"] = "¡REVIVIR es caro,\npero revive a los\fPOKéMON\ndebilitados!",
  ["_SaffronMartSuperNerdText"] = "¡MÁX. REPEL dura\nmás que el SÚPER\fREPEL en cuanto\na mantener lejos\fa los POKéMON\ndébiles!",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "Gracias por\nescribir. ¡Espero\fverte pronto!\f¡Oye! ¡No mires\nmi carta!",
  ["_SaffronPidgeyHousePaperText"] = "Recibí MÁS PP\ncomo regalo.\f¡Sirve para\naumentar los PP\fde los ataques!",
  ["_SaffronPidgeyHousePidgeyText"] = "PIDGEY: ¡Pid pid!",
  ["_SaffronPidgeyHouseYoungsterText"] = "¡La COPIONA es\nmuy mona! ¡Le\fvoy a dar una\nPOKé MUÑECA!",
  ["_SaffronPokecenterBeautyText"] = "La velocidad de\ncrecimiento de\flos POKéMON\nvaría de una\fespecie a otra.",
  ["_SaffronPokecenterGentlemanText"] = "SILPH S.A. es muy\nfamosa. ¡Por eso\fel TEAM ROCKET\ntiene tanto\finterés en ella!",
  ["_SandshrewDexEntry"] = "Se oculta bajo\ntierra, en zonas\fáridas y alejadas\fdel agua. Sólo\nemerge para cazar\fsu comida",
  ["_SandslashDexEntry"] = "Ante el peligro\nse acurruca en un\fespinoso ovillo.\fDe esta forma\npuede rodar para\fatacar o escapar",
  ["_SaveOptionText"] = "En la pantalla\ndel MENÚ está la\fopción GUARDAR.",
  ["_SavingEnergyText"] = "¡{USER}\nguarda energía!",
  ["_ScaredText"] = "¡{RAM:wBattleMonNick} está\ntan asustado que\fno puede moverse!",
  ["_ScytherDexEntry"] = "Con una agilidad\ny velocidad tipo-\fninja, puede\fcrear la ilusión\nde que hay más\fde uno",
  ["_SeadraDexEntry"] = "Puede nadar hacia\natrás moviendo\frápidamente sus\faletas pectorales\ny su robusta\fcola",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "¡Ar Tic!",
  ["_SeafoamIslandsB4FBouldersSignText"] = "¡Las ROCAS pueden\ncambiar el flujo\fdel agua!",
  ["_SeafoamIslandsB4FDangerSignText"] = "¡PELIGRO!\n¡Rápidos!",
  ["_SeakingDexEntry"] = "En otoño, cuando\nse reproducen,\fpueden ser vistos\fnadando con\nenergía por ríos\fy arroyos",
  ["_SeelDexEntry"] = "El cuerno que\nsobresale de su\fcabeza es muy\fduro. Suele\nusarlo para\fromper el hielo",
  ["_SentToBoxText"] = "¡No tienes sitio\npara más POKéMON!\f¡{RAM:wBoxMonNicks}\nfue enviado a la\fCAJA POKéMON\n{RAM:wStringBuffer} del PC!",
  ["_ShallWeHealYourPokemonText"] = "¿Quieres que\ncuremos a tus\fPOKéMON?",
  ["_ShellderDexEntry"] = "Su caparazón\nrepele cualquier\ftipo de ataque.\fSólo cuando abre\nsu caparazón es\fvulnerable",
  ["_ShroudedInMistText"] = "¡{USER}\npadece neblina!",
  ["_SilphCo10FGiovanniILostAgainText"] = "¡¡Arr!!\n¿¡He vuelto a\fperder!?",
  ["_SilphCo10FPorygonText"] = "¡Hay un POKéMON\nen el monitor!",
  ["_SilphCo10FRocketAfterBattleText"] = "¡Bien jugado,\npero la sala del\fconsejo está un\npiso más arriba!",
  ["_SilphCo10FRocketBattleText"] = "¡Bienvenido al\nnoveno piso!\f¡Me alegra que\nhayas venido!",
  ["_SilphCo10FRocketEndBattleText"] = "¡Estoy\naturdido!",
  ["_SilphCo10FScientistAfterBattleText"] = "¿Te alegra\nhaberme ganado?\f¡Pues vete a casa!",
  ["_SilphCo10FScientistBattleText"] = "¡Ya está bien\nde tonterías!",
  ["_SilphCo10FScientistEndBattleText"] = "¡No\nme quedan\fcontinuaciones!",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "¡Uauuu!\n¡Tengo miedo!",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "¡Por favor, no le\ndigas a nadie que\fhe llorado!",
  ["_SilphCo11FBeautyText"] = "SECRETARIA:\n¡Gracias por\fsalvarnos!\fAdmiramos\ntu valor.",
  ["_SilphCo11FGiovanniText"] = "¡Hola {PLAYER}!\n¡Volvemos a\fencontrarnos!\f¡El PRESIDENTE y\nyo estamos\fhablando de algo\nmuy importante!\f¡No te metas\nen los asuntos\fde los mayores!\f¡O sufrirás\nmi ira!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "¡Qué mal!\n¡Arruinaste\fnuestros planes\ncon respecto a\fSILPH!\f¡Pero el TEAM\nROCKET no caerá\fjamás!\f¡{PLAYER}, no\nolvides jamás\fque todos los\nPOKéMON son\fpara el\nTEAM ROCKET!\f¡Ahora debo irme,\npero volveré!",
  ["_SilphCo11FRocket1AfterBattleText"] = "¿¡Qué!? ¿Quieres\nver a mi JEFE?",
  ["_SilphCo11FRocket1BattleText"] = "¡Alto ahí!\n¡No te muevas!",
  ["_SilphCo11FRocket1EndBattleText"] = "No...\n¡Por favor!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Ten cuidado,\n¡Los POKéMON\fde mi JEFE son\nterribles!",
  ["_SilphCo11FRocket2BattleText"] = "¡Alto! ¿Tienes\nuna cita con\fmi JEFE?",
  ["_SilphCo11FRocket2EndBattleText"] = "¡Auch!\n¡Derribado!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PRESIDENTE: ¡No\npuedes comprarla\fen ningún sitio!\f¡Es nuestro\nprototipo secreto\fde la\nMASTER BALL!\f¡Puede atrapar a\ncualquier tipo\fde POKéMON!\fPero mejor que\nno se lo digas\fa nadie.",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "No tienes sitio\npara esto.",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "¡{PLAYER} ganó\n{RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PRESIDENTE:\n¡Gracias por\fsalvar a SILPH!\f¡Jamás olvidaré\nque nos salvaste\fen este peligroso\nmomento!\f¡Me gustaría\nagradecértelo\fde alguna forma!\fComo soy rico,\n¡puedo darte\flo que quieras!\f¡Toma, puede que\nte interese!",
  ["_SilphCo1FLinkReceptionistText"] = "¡Bienvenido!\f¡El PRESIDENTE\nestá en la sala\fde reuniones\ndel P10!",
  ["_SilphCo2FRocket1AfterBattleText"] = "¡Las baldosas con\nforma de diamante\fson puntos de\nteletransporte!\f¡Son medios de\ntransporte de\falta tecnología!",
  ["_SilphCo2FRocket1BattleText"] = "¡Aquí no pueden\nentrar los niños!",
  ["_SilphCo2FRocket1EndBattleText"] = "\n¡Muy fuerte!",
  ["_SilphCo2FRocket2AfterBattleText"] = "¡SILPH S.A. va a\nfusionarse con\fel TEAM ROCKET!",
  ["_SilphCo2FRocket2BattleText"] = "¡Oye tú, niño!\n¿Qué haces aquí?",
  ["_SilphCo2FRocket2EndBattleText"] = "¡He\nmetido la pata!",
  ["_SilphCo2FScientist1AfterBattleText"] = "¡Trabajo para\nSILPH S.A. y para\fel TEAM ROCKET!",
  ["_SilphCo2FScientist1BattleText"] = "¡Socorro! ¡Soy\nun empleado de\fSILPH S.A.!",
  ["_SilphCo2FScientist1EndBattleText"] = "\n¿Cómo sabías que\fyo era un ROCKET?",
  ["_SilphCo2FScientist2AfterBattleText"] = "¿Puedes resolver\neste laberinto?",
  ["_SilphCo2FScientist2BattleText"] = "¡Estás en zona\nprohibida!\f¡Vuelve a casa!",
  ["_SilphCo2FScientist2EndBattleText"] = "¡Eres\nmuy bueno!",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "¡{PLAYER} obtiene\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "¡La MT36 es\nAUTODESTRUCCIÓN!\f¡Es muy potente,\npero el POKéMON\fque la use se\ndebilitará mucho!\f¡Ten cuidado!",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "¡No tienes sitio\npara esto!",
  ["_SilphCo3FRocketAfterBattleText"] = "¿Una pista? ¡Para\nabrir las puertas\futiliza una\nLLAVE MAGNÉTICA!",
  ["_SilphCo3FRocketBattleText"] = "¡Niño, no nos\nmolestes más!",
  ["_SilphCo3FRocketEndBattleText"] = "\n¡Me rindo!",
  ["_SilphCo3FScientistAfterBattleText"] = "Mmmm...\f¡El TEAM ROCKET\nme dijo que si\flos ayudaba, me\ndejarían estudiar\fa los POKéMON!",
  ["_SilphCo3FScientistBattleText"] = "¡¡¡Apoyo más al\nTEAM ROCKET que\fa SILPH S.A.!!!",
  ["_SilphCo3FScientistEndBattleText"] = "¡Me\nhas derrotado!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Trabajo para\nSILPH S.A. ¿Qué\fdebería hacer?",
  ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "¡{PLAYER}! ¡Tú\ny tus POKéMON\fnos habéis\nsalvado!",
  ["_SilphCo4FRocket1AfterBattleText"] = "¡Ja ja ja! ¡Mi\nJEFE buscaba\feste lugar!",
  ["_SilphCo4FRocket1BattleText"] = "¡El TEAM ROCKET\nse ha apoderado\fde SILPH S.A.!",
  ["_SilphCo4FRocket1EndBattleText"] = "¡Arrgh!",
  ["_SilphCo4FRocket2AfterBattleText"] = "¡Será mejor que se\nlo diga al JEFE\fdel décimo piso!",
  ["_SilphCo4FRocket2BattleText"] = "¡Intruso\nlocalizado!",
  ["_SilphCo4FRocket2EndBattleText"] = "¿Quién\neres tú?",
  ["_SilphCo4FScientistAfterBattleText"] = "¡Las puertas\nestán cerradas\felectrónicamente!\n¡Las abre una\fLLAVE MAGNÉTICA!",
  ["_SilphCo4FScientistBattleText"] = "¡Mis POKéMON\nson mis fieles\fsoldados!",
  ["_SilphCo4FScientistEndBattleText"] = "\n¡Debilitaste a\fmi POKéMON!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "¡Sssh! ¿Acaso no\nves que me estoy\fescondiendo?",
  ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "¿Eh? ¿Que el TEAM\nROCKET se ha ido?",
  ["_SilphCo5FPokemonReport1Text"] = "¡Un INFORME sobre\nlos POKéMON!\fPORYGON, el \nprimer POKéMON\fvirtual, se creó\nen el LABORATORIO\fPOKéMON.",
  ["_SilphCo5FPokemonReport2Text"] = "¡Un INFORME sobre\nlos POKéMON!\f¡Confirmados más\nde 160 ataques\fde POKéMON!",
  ["_SilphCo5FPokemonReport3Text"] = "¡Un INFORME sobre\nlos POKéMON!\f¡Hay 4 POKéMON\nque sólo se\fdesarrollan si\nse intercambian\fvía cable-link!",
  ["_SilphCo5FRockerAfterBattleText"] = "¡Sólo has llegado\nal 4P! ¡Mi JEFE\faún está muy\nlejos!",
  ["_SilphCo5FRockerBattleText"] = "¿Qué? ¡Aquí no\ndebería haber\fningún niño!",
  ["_SilphCo5FRockerEndBattleText"] = "\n¡Oh no!\f¡Dios mío!",
  ["_SilphCo5FRocket1AfterBattleText"] = "¡No es que sea\nmuy inteligente\fprovocar al\nTEAM ROCKET!",
  ["_SilphCo5FRocket1BattleText"] = "Dicen que había\nun niño por\faquí.",
  ["_SilphCo5FRocket1EndBattleText"] = "¡Boooom!",
  ["_SilphCo5FRocket2AfterBattleText"] = "Eso me recuerda\nque...\f¡KOFFING se\ntransforma en\fWEEZING!",
  ["_SilphCo5FRocket2BattleText"] = "¡Respeta un poco\nal TEAM ROCKET!",
  ["_SilphCo5FRocket2EndBattleText"] = "\n(Tos)... (Tos)...",
  ["_SilphCo5FScientistAfterBattleText"] = "¡Trabajamos en\nuna nueva\fPOKé BALL capaz\nde atraparlo\ftodo!",
  ["_SilphCo5FScientistBattleText"] = "¡En este piso\nestudiamos la\ftecnología de\nlas POKé BALL!",
  ["_SilphCo5FScientistEndBattleText"] = "¡Uff!\n¡Maldición!",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "El TEAM ROCKET\nestá buscando a\fun intruso. Te\nbuscan a ti ¿no?",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "¡El TEAM ROCKET\nse fue! ¡Gracias!\f¡Eres un héroe!",
  ["_SilphCo6FRocket1AfterBattleText"] = "¡No importa!\n¡Mis hermanos me\fvengarán!",
  ["_SilphCo6FRocket1BattleText"] = "¡Soy uno de los 4\nHERMANOS ROCKET!",
  ["_SilphCo6FRocket1EndBattleText"] = "\n¡Chamuscado!",
  ["_SilphCo6FRocket2AfterBattleText"] = "¡Si apoyas\nla justicia,\ftraicionarás\nal malvado!",
  ["_SilphCo6FRocket2BattleText"] = "¿Te atreviste a\ntraicionar al\fTEAM ROCKET?",
  ["_SilphCo6FRocket2EndBattleText"] = "¡Eres\nun traidor!",
  ["_SilphCo6FScientistAfterBattleText"] = "¿La SUCURSAL\nTIKSI? ¡Está\fen mitad de\nla nada!",
  ["_SilphCo6FScientistBattleText"] = "¡Ese podrido\nPRESIDENTE!\f¡No debía haberme\nenviado a la\fSUCURSAL TIKSI!",
  ["_SilphCo6FScientistEndBattleText"] = "\n¡Estoy acabado!",
  ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "¡Me daba tanta\npena, que decidí\fcasarme con él!",
  ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "¡Mírale! ¡Es\ntan cobarde!",
  ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "¡El TEAM ROCKET\nquiere conquistar\fel mundo con sus\nPOKéMON!",
  ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "¡El TEAM ROCKET\nse escapó por\ftu culpa!",
  ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "¡Mejor volver\nal trabajo!",
  ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "¡Los ROCKET\nvinieron y se\fapoderaron de\ntodo el edificio!",
  ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "SILPH parece\ninteresarles\fpor nuestros\nproductos\fPOKéMON.",
  ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "¡Ven a trabajar\npara SILPH cuando\fseas mayor!",
  ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "¡Oh, por favor!\n¡Ayúdame!",
  ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "¡Somos novios!\n¡Jaja!",
  ["_SilphCo7FRivalDefeatedText"] = "¡Ajá!\n¡Así que ya estás\flisto para luchar\ncontra el\fJEFE ROCKET!",
  ["_SilphCo7FRivalGoodLuckToYouText"] = "¡Bien {PLAYER}!\f¡Sigo mejorando\ny avanzando!\f¡Chequeando mi\nPOKéDEX puedo\fsaber cuáles son\nlos más fuertes y\fcómo evolucionan!\f¡Voy a la LIGA\nPOKéMON para\fderrotar al\nALTO MANDO!\f¡Voy a ser el\nmejor entrenador\fdel mundo!\f¡{PLAYER}, que\ntengas suerte!\f¡No sudes tanto!\n¡Hasta luego!",
  ["_SilphCo7FRivalText"] = "{RIVAL}: ¿Qué te\nretrasó, {PLAYER}?",
  ["_SilphCo7FRivalVictoryText"] = "{RIVAL}: Cómo\ndecírtelo...\f¡No eres tan\nbueno como para\fjugar con los\nmayores!",
  ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}: ¡Jaja!\n¡Sabía que\faparecerías si\nesperaba aquí!\f¡Supongo que el\nTEAM ROCKET te\fretrasó! ¡Aunque\nno es que me\fimporte!\f¡Te vi en la\nCIUDAD AZAFRÁN, y\fdecidí esperar a\nver si mejorabas!",
  ["_SilphCo7FRocket1AfterBattleText"] = "¡No encontrarás a\nmi JEFE con sólo\fmerodear por ahí!",
  ["_SilphCo7FRocket1BattleText"] = "¡Oh, oh!\n¡Huelo a rata!",
  ["_SilphCo7FRocket1EndBattleText"] = "\n¡Luces fuera!",
  ["_SilphCo7FRocket2AfterBattleText"] = "No importa.\n¡Mis hermanos te\fdevolverán el\nfavor!",
  ["_SilphCo7FRocket2BattleText"] = "¡Soy uno de los 4\nHERMANOS ROCKET!",
  ["_SilphCo7FRocket2EndBattleText"] = "\n¡Auch! ¡Hermanos,\fhe perdido!",
  ["_SilphCo7FRocket3AfterBattleText"] = "¡Vete a casa\nantes de que se\fenfade mi JEFE!",
  ["_SilphCo7FRocket3BattleText"] = "¿Un niño intruso?\n¡Debes de ser tú!",
  ["_SilphCo7FRocket3EndBattleText"] = "¡Vale!\n¡He perdido!",
  ["_SilphCo7FScientistAfterBattleText"] = "¡A pesar de tu\nedad, eres un\fbuen entrenador!",
  ["_SilphCo7FScientistBattleText"] = "¡Ejem!\f¿Me confundiste\ncon un empleado\fde SILPH?",
  ["_SilphCo7FScientistEndBattleText"] = "\n¡Estoy acabado!",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "¡Ah! ¡Hola! ¡No\neres un ROCKET!\f¿Has venido a\nsalvarnos?\f¡Pues gracias!\fVoy a darte este\nPOKéMON por\fhabernos salvado.",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "¡El JEFE del TEAM\nROCKET fue a la \fsala del consejo!\n¿Está bien el\fPRESIDENTE?",
  ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "Es LAPRAS. Y es\nmuy inteligente.\f¡Lo teníamos en\nel laboratorio,\fpero estará mucho\nmejor contigo!\f¡Serás un buen\nentrenador\fpara LAPRAS!\fEs un buen\nnadador. ¡Podría\fllevarte!",
  ["_SilphCo7FSilphWorkerM1SavedText"] = "¡Salvados!\n¡Muchas gracias!",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "¡El TEAM ROCKET\nbuscaba la MASTER\fBALL para\npoder atrapar\fcualquier tipo\nde POKéMON!",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Cancelamos el\nproyecto de la\fMASTER BALL por\nculpa del\fTEAM ROCKET.",
  ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "¡Sería horrible\nque el TEAM\fROCKET se hiciera\ncon SILPH S.A.\fo con nuestros\nPOKéMON!",
  ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "¡Uauu! ¿Echaste\nal TEAM ROCKET\ftú solo?",
  ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "¡Oye! ¡Este lugar\nes muy peligroso!\f¿Has venido a\nsalvarme? ¡Pues\fno puedes!",
  ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "¡Por fin a salvo!\n¡Muchas gracias!",
  ["_SilphCo8FRocket1AfterBattleText"] = "¡Si no retrocedes\npediré refuerzos!",
  ["_SilphCo8FRocket1BattleText"] = "¡No podrás ir\nmás lejos!",
  ["_SilphCo8FRocket1EndBattleText"] = "¡No eres\ntan valiente!",
  ["_SilphCo8FRocket2AfterBattleText"] = "¡Mis hermanos se\nencargarán de ti!",
  ["_SilphCo8FRocket2BattleText"] = "¡Soy uno de los 4\nHERMANOS ROCKET!",
  ["_SilphCo8FRocket2EndBattleText"] = "¡Quiénes!\n¡Oh, hermanos!\f¡Debéis vengarme!",
  ["_SilphCo8FScientistAfterBattleText"] = "¿Qué opinas del\nlaberinto del\fEDIFICIO SILPH?",
  ["_SilphCo8FScientistBattleText"] = "¡Nos estás dando\nmuchos problemas!",
  ["_SilphCo8FScientistEndBattleText"] = "¿Qué?\n¿He perdido?",
